    wolf_form = get_node("WolfForm")
    bird_form = get_node("BirdForm")
    wolf_form.show()
    bird_form.hide()

func _process(delta):
    # Update the sanity system
    sanity -= sanity_loss_rate * delta

    # Check for shape-shifting input
    if Input.is_key_pressed(KEY_X):
        toggle_form()

func toggle_form():
    # Toggle between wolf and bird forms
    wolf_form.hide()
    bird_form.show()
    wolf_form = bird_form
    bird_form = wolf_form
```
